module mounting_hole_pattern() {
    hx = mounting_hole_spacing_x/2;
    hy = mounting_hole_spacing_y/2;

    // Clamp spacing to fit inside block with margin
    hx2 = min(hx, length/2 - edge_margin);
    hy2 = min(hy, width/2  - edge_margin);

    for (x = [-hx2, hx2])
