// Chamfered rectangular prism using Minkowski (keeps ONE connected solid)
module chamfered_block(size=[10,10,10], c=1) {
    inner = [max(eps, size[0]-2*c), max(eps, size[1]-2*c), max(eps, size[2]-2*c)];
    minkowski() {
        cube(inner, center=true);
        polyhedron(
            points=[
