        hole_x = outer_w/2 - mounting_hole_offset_x;
        for (sx = [-1, 1]) {
            translate([sx*hole_x, mounting_hole_y, -flange_thickness - 2*ov])
                cylinder(h=flange_thickness + 4*ov, d=mounting_hole_diameter, center=false);
