    x0 = -total_w/2;
    y0 = -(pin_pitch_y/2);

    // Start pins slightly inside the shell so they fuse (no floating)
    z0 = -pin_len + ov;

    for (row = [0:pin_rows-1]) {
        y = y0 + row*pin_pitch_y;
        for (i = [0:pins_per_row-1]) {
