    // Z stacking (centered around PCB midplane)
    pcb_z        = 0;
    bezel_z      = pcb_t/2 + bezel_t/2 - 0.2; // slight overlap into PCB
    blob_z       = -pcb_t/2 - blob_t/2 + 0.2; // slight overlap into PCB

