        union() {
            // --- Front flange (exact 36x27) ---
            translate([0, 0, -flange_t/2])
                linear_extrude(height=flange_t, center=true)
                    rounded_rect_2d(face_w, face_h, 1.6);

            // --- Rear body (connected to flange) ---
