module heat_set_insert_body() {
    union() {
        main_body_with_chamfers();
        external_barbs();
    }
}

module main_body_with_chamfers() {
    union() {
        // main cylinder
        cylinder(h = len, d = od, center = false);

        // top chamfer (lead-in)
        translate([0, 0, len - chamfer_h])
            cylinder(h = chamfer_h, d1 = od, d2 = chamfer_d, center = false);

