        // Main blue body with all orange features CUT INTO it (not floating)
        difference() {
            union() {
                socket_body();
                faceplate_profile();
            }
            // Cutouts go slightly beyond the full depth to ensure clean boolean
            pin_apertures();
            internal_hollow();
            mounting_screw_holes();
        }
    }
