// Overlap to guarantee connectivity (use 1–2mm as required)
ov = 1.2;

// ---------- Helpers ----------
module rounded_box(size=[10,10,10], r=1, center=true) {
    minkowski() {
        cube([max(0.01,size[0]-2*r), max(0.01,size[1]-2*r), max(0.01,size[2]-2*r)], center=center);
        sphere(r=r);
    }
