module panel_meter() {
    // Coordinate system:
    // Front face of bezel at z=0, model extends to negative z.
    union() {
        bezel_front();
        rear_body();
        side_latches();          // fixed: guaranteed overlap into bezel
        top_bottom_tabs();       // added: fixed floating top/bottom protrusions
