        cube([n*pitch, base_w, base_h], center=true);

        // Pins (connected into base with overlap)
        for (i = [0:n-1]) {
            translate([-(n-1)*pitch/2 + i*pitch, 0, base_h/2 + pin_h/2 - overlap])
                cube([pin_w, pin_w, pin_h], center=true);
