module pcb_plate(){
    linear_extrude(height=pcb_T, center=true)
        rounded_rect_2d(pcb_L, pcb_W, corner_r);
}

module mount_holes(){
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx*(pcb_L/2 - hole_edge), sy*(pcb_W/2 - hole_edge), 0])
            cylinder(h=pcb_T + 2, d=hole_d, center=true);
