module component_box(size_xyz, pos_xy){
    translate([pos_xy[0], pos_xy[1], pcb_T/2 + size_xyz[2]/2 - ov])
        cube(size_xyz, center=true);
}

// Places a cylinder component sitting on top surface of PCB with slight overlap
