    // Fins on top, overlapping into base
    fin_t = 1.2;
    fin_gap = 2.2;
    fin_h = heatsink_h * 0.75;
    fin_count = floor((heatsink_d - fin_t) / fin_gap);

    for (i = [0:fin_count-1]) {
