ear_inset = 0.6;

// Mounting holes (through PCB)
hole_r = 1.5;
hole_edge_clear = 2.6; // from OUTERMOST outline (incl. ears) to hole center

// Connectivity overlap (ensures one connected solid)
z_overlap = 0.25;
xy_overlap = 0.25;

// =====================
// Component sizes (simple but board-like)
// =====================
