driver_h = 2.2; driver = [9, 9, driver_h];

// =====================
// Helpers
// =====================
module pcb_outline_2d() {
    union() {
        square([pcb_w, pcb_l], center=true);

        ex = pcb_w/2 + ear_r - ear_inset;
        ey = pcb_l/2 + ear_r - ear_inset;

        translate([ ex,  ey]) circle(r=ear_r);
        translate([-ex,  ey]) circle(r=ear_r);
        translate([ ex, -ey]) circle(r=ear_r);
        translate([-ex, -ey]) circle(r=ear_r);
    }
