        conn_x = -pcb_length/2 + conn_l/2 + 1.0;
        conn_y = 0;
        translate([conn_x, conn_y, pcb_thickness + conn_h/2 - overlap])
            cube([conn_l, conn_w, conn_h], center=true);
    }
}

module stepper_driver_board() {
    union() {
        // PCB (with optional holes)
        if (use_mounting_holes) {
            difference() {
                pcb_solid();
                mounting_holes();
