        // Two long pin headers along the long edges
        header_inset = 1.0;
        header_y = pcb_width/2 - header_inset - header_body_w/2;

        translate([0,  header_y, 0]) header_1xN_with_pins();
        translate([0, -header_y, 0]) header_1xN_with_pins();

