    translate([0,0,hub_z0])
        cylinder(h=hub_length + 2*z_overlap, d=hub_diameter, center=true);
}

module pulley() {
    difference() {
        union() {
            toothed_ring();
            flanges();
            hub();
        }

        // Bore through entire part
        cylinder(h=pulley_total_h + hub_length + 4, d=bore_diameter, center=true);

