        // top chamfer: extend above total_h to guarantee intersection
        translate([0,0,total_h - chamfer_h - overlap])
            cylinder(h=chamfer_h + 2*overlap,
                     r1=max(r - chamfer_h, 0.01),
                     r2=r,
                     center=false);
