    linear_extrude(height=length, twist=turns*360, slices=max(ceil(turns*40), 80), convexity=10)
        translate([r_minor, 0, 0])
            polygon(points=[
                [0, -pitch*0.22],
                [r_major - r_minor, 0],
                [0,  pitch*0.22]
            ]);
