function R_from_sagitta(D, h) = ( (D/2)*(D/2) + h*h ) / (2*h); // sphere radius from base diameter & cap height

module hex_prism(af, h, center=false) {
    // Regular hex with across-flats = af
    // circumradius = af / sqrt(3)
