head_height    = 3.05;    // pan head height

// Thread approximation parameters
pitch          = 1.4;
thread_depth   = 0.35;
minor_diameter = screw_diameter - 2*thread_depth;

// Tip parameters
tip_len        = 1.2;     // tapered tip length (within shank)
tip_flat       = 0.25;    // flat at very end

// Numerical
eps = 0.05;

// Derived
