        translate([base_w/2 - split_w/2, (base_d - block_d)/2 - 1, cradle_cz - cradle_r - 2])
            cube([split_w, block_d/2 + 2, (block_z1 - (cradle_cz - cradle_r - 2)) + 1], center=false);

